/**
 *
 * DataTablePagination exposes pagination state and callbacks via render prop,
 * allowing users to compose their own pagination UI.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTablePagination
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseDataTablePageEvent } from '@primereact/types/headless/datatable';
import * as React from 'react';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTablePagination component.
 */
export type DataTablePaginationPassThroughType<E> = PassThroughType<DataTablePaginationInstance, E>;
/**
 * Defines passthrough(pt) options of DataTablePagination component.
 */
export interface DataTablePaginationPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTablePaginationPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DataTablePagination component.
 */
export interface DataTablePaginationProps extends BaseComponentProps<DataTablePaginationInstance, unknown, DataTablePaginationPassThrough> {
}
/**
 * Defines valid state in DataTablePagination component.
 */
export interface DataTablePaginationState {
}
/**
 * Slot context exposed to the `children` render prop and on the component instance.
 */
export interface DataTablePaginationExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
    /**
     * Current page index (0-based). Returns `0` when pagination is not active.
     */
    page: number;
    /**
     * Total number of pages.
     */
    pageCount: number;
    /**
     * Number of rows per page.
     */
    rows: number;
    /**
     * Total number of records.
     */
    totalRecords: number;
    /**
     * Index of the first record on the current page.
     */
    first: number;
    /**
     * Whether there is a previous page.
     */
    canPrev: boolean;
    /**
     * Whether there is a next page.
     */
    canNext: boolean;
    /**
     * Navigate to a specific page.
     */
    onPageChange: (event: React.SyntheticEvent, page: number) => void;
    /**
     * Change the number of rows per page.
     */
    onRowsChange: (event: React.SyntheticEvent, rows: number) => void;
}
/**
 * Instance of DataTablePagination component.
 */
export type DataTablePaginationInstance = ComponentInstance<DataTablePaginationProps, DataTablePaginationState, DataTablePaginationExposes>;
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTablePageEvent`.
 */
export interface DataTablePageEvent extends UseDataTablePageEvent {
}
